export interface Message {
  room: string;
  seq: number;
  user: string;
  text: string;
  ts: number;
}

import Database from 'better-sqlite3';
import path from 'node:path';

const globalInit = globalThis as any;

if (!globalInit.db) {
  const dbPath = path.join(process.cwd(), 'chat.db');
  const db = new Database(dbPath);

  // Enable WAL mode for better concurrency if needed, but standard is fine too
  db.pragma('journal_mode = WAL');

  // Create messages table
  db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      room TEXT NOT NULL,
      seq INTEGER NOT NULL,
      user TEXT NOT NULL,
      text TEXT NOT NULL,
      ts INTEGER NOT NULL,
      PRIMARY KEY (room, seq)
    );
    CREATE INDEX IF NOT EXISTS idx_messages_room_seq ON messages (room, seq);
  `);

  globalInit.db = db;
}

export const db = globalInit.db as Database.Database;

import type { Message } from './types';

export class Subscriber {
  readonly id: string;
  readonly room: string;
  private writer: any; // Use any to avoid type issues with different WritableStream versions
  private encoder = new TextEncoder();
  private queue: Message[] = [];
  private highestSentSeq: number = 0;
  private isLive = false;
  private isClosed = false;

  constructor(id: string, room: string, writer: any, initialSeq: number) {
    this.id = id;
    this.room = room;
    this.writer = writer;
    this.highestSentSeq = initialSeq;
  }

  // Called by the broker when a new message is published
  public handleMessage(message: Message) {
    if (this.isClosed) return;

    if (this.isLive) {
      this.sendOrQueue(message);
    } else {
      this.queue.push(message);
    }
  }

  private async sendOrQueue(message: Message) {
    if (message.seq <= this.highestSentSeq) {
      return; // Skip duplicate
    }
    this.highestSentSeq = message.seq;
    try {
      const sseString = `id: ${message.seq}\nevent: message\ndata: ${JSON.stringify({
        room: message.room,
        seq: message.seq,
        user: message.user,
        text: message.text,
        ts: message.ts
      })}\n\n`;
      await this.writer.write(this.encoder.encode(sseString));
    } catch (err) {
      // Stream might be closed or aborted
    }
  }

  // Called after replay messages have been sent
  public async transitionToLive(replayMessages: Message[]) {
    // 1. Send all replay messages
    for (const msg of replayMessages) {
      await this.sendOrQueue(msg);
    }

    // 2. Mark as live
    this.isLive = true;

    // 3. Drain queue
    const pending = this.queue;
    this.queue = [];
    for (const msg of pending) {
      await this.sendOrQueue(msg);
    }
  }

  public close() {
    if (this.isClosed) return;
    this.isClosed = true;
    try {
      this.writer.releaseLock();
    } catch (err) {
      // Ignore
    }
  }
}

import type { Subscriber } from './subscriber';
import type { Message } from './types';

export class Broker {
  private rooms = new Map<string, Set<Subscriber>>();

  public getSubscriberCount(room: string): number {
    return this.rooms.get(room)?.size ?? 0;
  }

  public subscribe(room: string, subscriber: Subscriber) {
    let subs = this.rooms.get(room);
    if (!subs) {
      subs = new Set();
      this.rooms.set(room, subs);
    }
    subs.add(subscriber);
  }

  public unsubscribe(room: string, subscriber: Subscriber) {
    const subs = this.rooms.get(room);
    if (subs) {
      subs.delete(subscriber);
      if (subs.size === 0) {
        this.rooms.delete(room);
      }
    }
    subscriber.close();
  }

  public publish(message: Message) {
    const subs = this.rooms.get(message.room);
    if (subs) {
      for (const sub of subs) {
        sub.handleMessage(message);
      }
    }
  }
}

const globalInit = globalThis as any;

if (!globalInit.broker) {
  globalInit.broker = new Broker();
}

export const broker = globalInit.broker as Broker;

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '~/lib/db';
import { broker } from '~/lib/broker';
import type { Message } from '~/lib/types';

export const onPost: RequestHandler = async ({ params, parseBody, json }) => {
  const room = params.room;
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  let body: any;
  try {
    body = await parseBody();
  } catch (err) {
    return json(400, { error: "Malformed JSON body" });
  }

  if (!body || typeof body !== 'object') {
    return json(400, { error: "Invalid request body" });
  }

  if (!('user' in body) || !('text' in body)) {
    return json(400, { error: "Missing required fields: user and text are required" });
  }

  if (typeof body.user !== 'string' || typeof body.text !== 'string') {
    return json(400, { error: "Fields user and text must be strings" });
  }

  const user = body.user.trim();
  const text = body.text.trim();

  if (user.length < 1 || user.length > 64) {
    return json(400, { error: "User length must be between 1 and 64 characters after trimming" });
  }

  if (text.length < 1 || text.length > 2000) {
    return json(400, { error: "Text length must be between 1 and 2000 characters after trimming" });
  }

  const ts = Date.now();

  try {
    // Perform database operations in a transaction to ensure atomicity and gapless sequences
    const insertTx = db.transaction((r: string, u: string, t: string, timestamp: number): Message => {
      const row = db.prepare('SELECT MAX(seq) AS maxSeq FROM messages WHERE room = ?').get(r) as { maxSeq: number | null } | undefined;
      const nextSeq = (row?.maxSeq ?? 0) + 1;
      db.prepare('INSERT INTO messages (room, seq, user, text, ts) VALUES (?, ?, ?, ?, ?)').run(r, nextSeq, u, t, timestamp);
      return { room: r, seq: nextSeq, user: u, text: t, ts: timestamp };
    });

    const message = insertTx(room, user, text, ts);

    // Publish to the live subscribers
    broker.publish(message);

    return json(201, message);
  } catch (err: any) {
    return json(500, { error: err.message || "Failed to persist and broadcast message" });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '~/lib/db';
import { broker } from '~/lib/broker';
import { Subscriber } from '~/lib/subscriber';
import type { Message } from '~/lib/types';

export const onGet: RequestHandler = async ({ params, request, status, headers, getWritableStream, signal, json }) => {
  const room = params.room;
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  // Set the response status and headers for SSE BEFORE calling getWritableStream()
  status(200);
  headers.set('Content-Type', 'text/event-stream');
  headers.set('Cache-Control', 'no-cache, no-transform');
  headers.set('Connection', 'keep-alive');
  headers.set('X-Accel-Buffering', 'no');

  const writable = getWritableStream();
  const writer = writable.getWriter();

  // Parse Last-Event-ID header
  const lastEventIdHeader = request.headers.get('last-event-id');
  let lastEventId: number | null = null;
  if (lastEventIdHeader !== null) {
    const parsed = parseInt(lastEventIdHeader, 10);
    if (!isNaN(parsed)) {
      lastEventId = parsed;
    }
  }

  const initialSeq = lastEventId ?? 0;
  const subscriberId = Math.random().toString(36).substring(2, 15);
  const subscriber = new Subscriber(subscriberId, room, writer, initialSeq);

  // Subscribe to the broker BEFORE querying the database
  broker.subscribe(room, subscriber);

  // Setup abort/disconnect listener
  let isCleanedUp = false;
  const cleanup = () => {
    if (isCleanedUp) return;
    isCleanedUp = true;
    broker.unsubscribe(room, subscriber);
  };

  signal.addEventListener('abort', cleanup);

  try {
    // Fetch replay messages synchronously from SQLite
    let replayMessages: Message[] = [];
    if (lastEventId !== null) {
      replayMessages = db.prepare(
        'SELECT room, seq, user, text, ts FROM messages WHERE room = ? AND seq > ? ORDER BY seq ASC'
      ).all(room) as Message[];
    } else {
      replayMessages = db.prepare(
        'SELECT room, seq, user, text, ts FROM (SELECT room, seq, user, text, ts FROM messages WHERE room = ? ORDER BY seq DESC LIMIT 50) ORDER BY seq ASC'
      ).all(room) as Message[];
    }

    // Transition subscriber to live (sends replay, then drains queue, then goes live)
    await subscriber.transitionToLive(replayMessages);
  } catch (err) {
    cleanup();
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { broker } from '~/lib/broker';

export const onGet: RequestHandler = async ({ params, json }) => {
  const room = params.room;
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  const count = broker.getSubscriberCount(room);

  return json(200, {
    room,
    subscribers: count
  });
};

